#include "SFMLDisplay.hpp"
#include <SFML/System/Err.hpp>
#include <algorithm>
#include <iostream>
#include <sstream>

// Embedded font data (generated by CMake from graphics/assets/Inter.ttf)
namespace Arcade {
    extern const unsigned char INTER_FONT_DATA[];
    extern const unsigned int  INTER_FONT_SIZE;
}

namespace Arcade {

SFMLDisplay::~SFMLDisplay()
{
    close();
}

// ─── init / close ─────────────────────────────────────────────────────────────
void SFMLDisplay::init(const std::string& title)
{
    // Suppress SFML's internal diagnostic messages (e.g. "vertical sync not supported")
    // by redirecting sf::err() to a null sink for the duration of window creation.
    std::ostringstream sfmlSink;
    std::streambuf* prevErrBuf = sf::err().rdbuf(sfmlSink.rdbuf());

    _window = std::make_unique<sf::RenderWindow>(
        sf::VideoMode::getDesktopMode(),
        title,
        sf::State::Fullscreen);
    _window->setFramerateLimit(60);
    _window->setView(sf::View(sf::FloatRect(
        {0.f, 0.f}, {(float)WIN_W, (float)WIN_H})));

    sf::err().rdbuf(prevErrBuf);

    _fontLoaded = false;
    if (INTER_FONT_SIZE > 0)
    {
        _fontLoaded = _font.openFromMemory(INTER_FONT_DATA, INTER_FONT_SIZE);
    }

    if (!_fontLoaded)
    {
        std::cerr << "[SFML] Embedded Inter.ttf not available — text rendering disabled.\n";
    }

    _lastGrid = {};
    _lastRelX = _lastRelY = -1.f;
    _audioEnabled = sf::PlaybackDevice::getDefaultDevice().has_value();
    if (!_audioEnabled)
        std::cerr << "[SFML] No audio playback device found — audio disabled.\n";
}

void SFMLDisplay::close()
{
    if (_musicOpen && _music.has_value()) {
        _music->stop();
        _musicOpen = false;
    }
    _music.reset();
    if (_sound)
    {
        _sound->stop();
    }

    if (_window && _window->isOpen())
    {
        _window->close();
    }
    _window.reset();
}

// ─── Audio ────────────────────────────────────────────────────────────────────
void SFMLDisplay::playMusic(const unsigned char* data, unsigned int size, bool loop)
{
    if (_musicOpen && _music.has_value()) {
        _music->stop();
        _musicOpen = false;
    }
    _music.reset();
    if (!_audioEnabled || size == 0)
        return;
    _music.emplace();
    if (_music->openFromMemory(data, size))
    {
        _musicOpen = true;
        _music->setLooping(loop);
        _music->play();
    }
}

void SFMLDisplay::playSound(const unsigned char* data, unsigned int size)
{
    if (!_audioEnabled || size == 0)
        return;
    if (_soundBuffer.loadFromMemory(data, size))
    {
        _sound.emplace(_soundBuffer);
        _sound->play();
    }
}

void SFMLDisplay::stopMusic()
{
    if (_musicOpen && _music.has_value()) {
        _music->stop();
        _music.reset();
        _musicOpen = false;
    }
}

void SFMLDisplay::setVolume(int percent)
{
    if (_musicOpen && _music.has_value())
        _music->setVolume(static_cast<float>(std::clamp(percent, 0, 100)));
}

void SFMLDisplay::clear()
{
    if (_window)
    {
        _window->clear(sf::Color(0, 0, 0));
    }
}

void SFMLDisplay::display()
{
    if (_window)
    {
        _window->display();
    }
}

bool SFMLDisplay::isOpen() const
{
    return _window && _window->isOpen();
}

// ─── fillMouseEvent ───────────────────────────────────────────────────────────
void SFMLDisplay::fillMouseEvent(MouseEvent& mouseEvent, int pixelX, int pixelY) const
{
    mouseEvent.relativeX = std::clamp(pixelX / (float)WIN_W, 0.f, 1.f);
    mouseEvent.relativeY = std::clamp(pixelY / (float)WIN_H, 0.f, 1.f);
    mouseEvent.gridX = -1;
    mouseEvent.gridY = -1;

    if (_lastGrid.gridWidth > 0 && _lastGrid.cellSize > 0.f) {
        const float localX = (float)(pixelX - _lastGrid.originX);
        const float localY = (float)(pixelY - _lastGrid.originY);
        const int cellViewX = (int)(localX / _lastGrid.cellSize);
        const int cellViewY = (int)(localY / _lastGrid.cellSize);

        if (cellViewX >= 0 && cellViewX < _lastGrid.viewWidth &&
            cellViewY >= 0 && cellViewY < _lastGrid.viewHeight) {
            mouseEvent.gridX = _lastGrid.cameraX + cellViewX;
            mouseEvent.gridY = _lastGrid.cameraY + cellViewY;
        }
    }
}

// ─── Input ────────────────────────────────────────────────────────────────────
std::vector<Key> SFMLDisplay::getHeldKeys()
{
    std::vector<Key> held;
    auto check = [&](sf::Keyboard::Key sfKey, Key arcadeKey) {
        if (sf::Keyboard::isKeyPressed(sfKey)) held.push_back(arcadeKey);
    };
    check(sf::Keyboard::Key::Up,    Key::UP);
    check(sf::Keyboard::Key::Down,  Key::DOWN);
    check(sf::Keyboard::Key::Left,  Key::LEFT);
    check(sf::Keyboard::Key::Right, Key::RIGHT);
    check(sf::Keyboard::Key::W,     Key::W);
    check(sf::Keyboard::Key::A,     Key::A);
    check(sf::Keyboard::Key::S,     Key::S);
    check(sf::Keyboard::Key::D,     Key::D);
    check(sf::Keyboard::Key::Space, Key::SPACE);
    return held;
}

std::vector<Key> SFMLDisplay::getKeys()
{
    std::vector<Key> keys;

    if (!_window)
        return keys;

    _pendingMouseEvents.clear();
    _prevRelX = _lastRelX;
    _prevRelY = _lastRelY;

    while (const std::optional<sf::Event> ev = _window->pollEvent()) {
        if (ev->is<sf::Event::Closed>()) {
            _window->close();
            return keys;
        }
        if (const auto* keyPressed = ev->getIf<sf::Event::KeyPressed>()) {
            Key key = sfmlKey(keyPressed->code);
            if (key != Key::NONE)
                keys.push_back(key);
        }
        if (const auto* mouseButton = ev->getIf<sf::Event::MouseButtonPressed>()) {
            MouseEvent mouseEvent;
            fillMouseEvent(mouseEvent, mouseButton->position.x, mouseButton->position.y);
            if (mouseButton->button == sf::Mouse::Button::Left)
                mouseEvent.button = Key::MOUSE_LEFT;
            else if (mouseButton->button == sf::Mouse::Button::Middle)
                mouseEvent.button = Key::MOUSE_MIDDLE;
            else if (mouseButton->button == sf::Mouse::Button::Right)
                mouseEvent.button = Key::MOUSE_RIGHT;
            if (mouseEvent.button != Key::NONE)
                _pendingMouseEvents.push_back(mouseEvent);
        }
        if (const auto* mouseMoved = ev->getIf<sf::Event::MouseMoved>()) {
            fillMouseEvent(_pendingMouseEvents.emplace_back(), mouseMoved->position.x, mouseMoved->position.y);
            _lastRelX = _pendingMouseEvents.back().relativeX;
            _lastRelY = _pendingMouseEvents.back().relativeY;
        }
        if (const auto* textEntered = ev->getIf<sf::Event::TextEntered>()) {
            const auto unicodeChar = textEntered->unicode;
            // Skip '+' (43) and '-' (45) — those are volume-only keys
            if (unicodeChar >= 32 && unicodeChar < 127 && unicodeChar != '+' && unicodeChar != '-')
                _textInput += static_cast<char>(unicodeChar);
        }
    }
    return keys;
}

std::vector<MouseEvent> SFMLDisplay::getMouseEvents()
{
    return _pendingMouseEvents;
}

std::pair<float,float> SFMLDisplay::getMousePosition() const
{
    return {_lastRelX, _lastRelY};
}

bool SFMLDisplay::hasMouseMoved() const
{
    return _lastRelX != _prevRelX || _lastRelY != _prevRelY;
}

Key SFMLDisplay::sfmlKey(sf::Keyboard::Key key) const noexcept
{
    switch (key)
    {
        case sf::Keyboard::Key::Up:     return Key::UP;
        case sf::Keyboard::Key::Down:   return Key::DOWN;
        case sf::Keyboard::Key::Left:   return Key::LEFT;
        case sf::Keyboard::Key::Right:  return Key::RIGHT;
        case sf::Keyboard::Key::Enter:  return Key::ENTER;
        case sf::Keyboard::Key::Escape: return Key::ESCAPE;
        case sf::Keyboard::Key::Space:  return Key::SPACE;
        case sf::Keyboard::Key::Tab:    return Key::TAB;
        case sf::Keyboard::Key::F1:     return Key::F1;
        case sf::Keyboard::Key::F2:     return Key::F2;
        case sf::Keyboard::Key::F3:     return Key::F3;
        case sf::Keyboard::Key::F4:     return Key::F4;
        case sf::Keyboard::Key::Backspace: return Key::BACKSPACE;
        case sf::Keyboard::Key::Add:      return Key::PLUS;
        case sf::Keyboard::Key::Equal:    return Key::PLUS;
        case sf::Keyboard::Key::Subtract: return Key::MINUS;
        case sf::Keyboard::Key::Hyphen:   return Key::MINUS;
        default:
            if (key >= sf::Keyboard::Key::A && key <= sf::Keyboard::Key::Z)
                return static_cast<Key>(static_cast<int>(Key::A) +
                    (static_cast<int>(key) - static_cast<int>(sf::Keyboard::Key::A)));
            return Key::NONE;
    }
}

sf::Color SFMLDisplay::toSFML(const Color& c) const noexcept
{
    return {c.r, c.g, c.b, c.a};
}

std::string SFMLDisplay::getTextInput()
{
    std::string out;
    std::swap(out, _textInput);
    return out;
}

const sf::Texture* SFMLDisplay::getCachedImage(const unsigned char* data, unsigned int size)
{
    auto it = _imageCache.find(data);
    if (it != _imageCache.end())
        return &it->second;
    sf::Texture tex;
    if (!tex.loadFromMemory(data, size))
        return nullptr;
    return &_imageCache.emplace(data, std::move(tex)).first->second;
}

void SFMLDisplay::clearImageCache()
{
    _imageCache.clear();
}

// ─── drawGrid ─────────────────────────────────────────────────────────────────
void SFMLDisplay::drawGrid(const std::vector<Cell>& cells,
                            int gridWidth, int gridHeight,
                            float x1, float y1, float x2, float y2,
                            int focusX, int focusY,
                            const GridStyle& style)
{
    if (!_window || gridWidth <= 0 || gridHeight <= 0 || cells.empty())
    {
        return;
    }

    const float areaW = (x2 - x1) * WIN_W;
    const float areaH = (y2 - y1) * WIN_H;

    float cellSize = std::min(areaW / (float)gridWidth, areaH / (float)gridHeight);
    const bool needsCamera = (cellSize < DisplayConfig::MIN_CELL_PX);
    if (needsCamera)
        cellSize = DisplayConfig::MIN_CELL_PX;

    const int viewWidth  = needsCamera ? std::min(gridWidth,  (int)(areaW / cellSize)) : gridWidth;
    const int viewHeight = needsCamera ? std::min(gridHeight, (int)(areaH / cellSize)) : gridHeight;

    int cameraX = 0;
    int cameraY = 0;
    if (needsCamera && focusX >= 0)
        cameraX = std::clamp(focusX - viewWidth / 2, 0, std::max(0, gridWidth - viewWidth));
    if (needsCamera && focusY >= 0)
        cameraY = std::clamp(focusY - viewHeight / 2, 0, std::max(0, gridHeight - viewHeight));

    const int originX = (int)(x1 * WIN_W + (areaW - viewWidth  * cellSize) / 2.f);
    const int originY = (int)(y1 * WIN_H + (areaH - viewHeight * cellSize) / 2.f);

    _lastGrid = { gridWidth, gridHeight, cellSize, originX, originY, viewWidth, viewHeight, cameraX, cameraY };

    // Dark background
    const float border = style.borderPx;
    sf::RectangleShape bg({areaW + 2.f*border, areaH + 2.f*border});
    bg.setPosition({x1*WIN_W - border, y1*WIN_H - border});
    bg.setFillColor(toSFML(style.backgroundColor));
    _window->draw(bg);

    const unsigned fontSize = (unsigned)std::max(8, (int)(cellSize * 0.75f));

    for (int viewY = 0; viewY < viewHeight; ++viewY) {
        for (int viewX = 0; viewX < viewWidth; ++viewX) {
            const int gridX = cameraX + viewX;
            const int gridY = cameraY + viewY;

            if (gridX >= gridWidth || gridY >= gridHeight)
                continue;

            const Cell& cell = cells[gridY * gridWidth + gridX];

            const float px = (float)(originX + (int)(viewX * cellSize));
            const float py = (float)(originY + (int)(viewY * cellSize));
            const float cellWidth  = (float)(originX + (int)((viewX+1) * cellSize)) - px;
            const float cellHeight = (float)(originY + (int)((viewY+1) * cellSize)) - py;

            if (cell.imageData && cell.imageSize > 0) {
                const sf::Texture* imgTex = getCachedImage(cell.imageData, cell.imageSize);
                if (imgTex) {
                    sf::RectangleShape bgRect({cellWidth, cellHeight});
                    bgRect.setPosition({px, py});
                    bgRect.setFillColor(toSFML(cell.bgImage));
                    _window->draw(bgRect);

                    sf::Sprite sprite(*imgTex);
                    const auto sz = imgTex->getSize();
                    float scaleX = cellWidth / (float)sz.x;
                    float scaleY = cellHeight / (float)sz.y;
                    if (cell.imageFlipX) scaleX = -scaleX;
                    sprite.setOrigin({(float)sz.x / 2.f, (float)sz.y / 2.f});
                    sprite.setScale({scaleX, scaleY});
                    sprite.setPosition({px + cellWidth / 2.f, py + cellHeight / 2.f});
                    sprite.setRotation(sf::degrees(cell.imageAngle));
                    _window->draw(sprite);

                    if (cell.highlight) {
                        sf::RectangleShape hl({cellWidth, cellHeight});
                        hl.setPosition({px, py});
                        hl.setFillColor(toSFML(style.highlightColor));
                        _window->draw(hl);
                    }
                    continue;
                }
            }

            sf::RectangleShape rect({cellWidth, cellHeight});
            rect.setPosition({px, py});
            rect.setFillColor(toSFML(cell.bg));
            _window->draw(rect);

            if (cell.c != ' ' && _fontLoaded) {
                sf::Text txt(_font,
                    sf::String(static_cast<char32_t>(static_cast<unsigned char>(cell.c))),
                    fontSize);
                txt.setFillColor(toSFML(cell.fg));
                const sf::FloatRect b = txt.getLocalBounds();
                txt.setOrigin({b.position.x + b.size.x/2.f, b.position.y + b.size.y/2.f});
                txt.setPosition({px + cellWidth/2.f, py + cellHeight/2.f});
                _window->draw(txt);
            }

            if (cell.highlight) {
                sf::RectangleShape hl({cellWidth, cellHeight});
                hl.setPosition({px, py});
                hl.setFillColor(toSFML(style.highlightColor));
                _window->draw(hl);
            }
        }
    }
}

// ─── drawText ─────────────────────────────────────────────────────────────────
void SFMLDisplay::drawText(const std::string& text, float relativeX, float relativeY,
                            const Color& fg, const Color*, float scale)
{
    if (!_window || !_fontLoaded || text.empty())
    {
        return;
    }

    const unsigned fontSize = (unsigned)std::max(8, (int)(DisplayConfig::BASE_FONT_SIZE * scale));
    sf::Text txt(_font, sf::String(text), fontSize);
    txt.setFillColor(toSFML(fg));
    const sf::FloatRect b = txt.getLocalBounds();
    txt.setOrigin({b.position.x + b.size.x/2.f, b.position.y + b.size.y/2.f});
    txt.setPosition({relativeX * WIN_W, relativeY * WIN_H});
    _window->draw(txt);
}

// ─── drawLine ─────────────────────────────────────────────────────────────────
void SFMLDisplay::drawLine(char c, float x1, float x2, float y,
                            const Color& fg, const Color& bg, float scale)
{
    if (!_window || x2 <= x1)
        return;

    const float px1 = x1 * WIN_W;
    const float px2 = x2 * WIN_W;
    const float py  = y  * WIN_H;
    const unsigned fontSize = (unsigned)std::max(8, (int)(DisplayConfig::BASE_FONT_SIZE * scale));
    const float lineH = static_cast<float>(fontSize) * 1.4f;

    // Background rectangle (top 10% trimmed — glyphs don't reach the top of their metrics box)
    const float bgH    = lineH * 0.9f;
    const float bgTopY = py - lineH / 2.f + lineH * 0.1f; // shift top edge down by 10%
    if (bg.r || bg.g || bg.b) {
        sf::RectangleShape strip({px2 - px1, bgH});
        strip.setPosition({px1, bgTopY});
        strip.setFillColor(toSFML(bg));
        _window->draw(strip);
    }

    // Tile the character across the line
    if (_fontLoaded && c != ' ') {
        // Estimate count from single-char width
        sf::Text probe(_font, sf::String(std::string(1, c)), fontSize);
        const float charW = probe.getLocalBounds().size.x + 1.f;
        if (charW > 0.f && px2 > px1) {
            int count = std::max(1, static_cast<int>((px2 - px1) / charW));
            // Verify with actual string bounds and trim until it fits
            sf::Text txt(_font, sf::String(std::string(count, c)), fontSize);
            while (count > 1 && txt.getLocalBounds().size.x > px2 - px1) {
                count--;
                txt.setString(std::string(count, c));
            }
            txt.setFillColor(toSFML(fg));
            const sf::FloatRect b = txt.getLocalBounds();
            txt.setOrigin({b.position.x, b.position.y + b.size.y / 2.f});
            txt.setPosition({px1, py});
            _window->draw(txt);
        }
    }
}

void SFMLDisplay::drawRect(float x1, float y1, float x2, float y2, const Color& color)
{
    if (!_window)
    {
        return;
    }
    sf::RectangleShape rect({(x2 - x1) * WIN_W, (y2 - y1) * WIN_H});
    rect.setPosition({x1 * WIN_W, y1 * WIN_H});
    rect.setFillColor(toSFML(color));
    _window->draw(rect);
}

} // namespace Arcade

extern "C" {
    Arcade::IDisplayModule* createDisplay() { return new Arcade::SFMLDisplay(); }
    void destroyDisplay(Arcade::IDisplayModule* d) { delete d; }
}
